{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "There is limited evidence to evaluate the sustainability of evidence-based interventions (EBIs) for healthcare improvement.",
      "reason": "The abstract explicitly describes the current state of knowledge (limited evidence) and uncertainties (unclear which approach is most effective)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "It is unclear which approach/approaches are most effective for evaluating sustainability and what measures and outcomes are most commonly used. There is a disconnect between evaluating the factors that may shape sustainability and the outcomes approaches employed to measure sustainability. Our review offers methodological recommendations for sustainability evaluation research and highlights the importance in understanding mechanisms of sustainability to advance the field.",
      "reason": "The abstract explains the importance and need for the review by highlighting the disconnect in current research and the value of the review's recommendations."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_20",
      "quote": "A focus on evaluation is what differentiates this review from recent syntheses published on approaches to sustainability research.",
      "reason": "The discussion explains the need for the current review by differentiating it from recent syntheses and citing previous work (e.g., Lennox et al.) to justify the specific focus on evaluation approaches."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is an integrative review of evaluation approaches, not a review of intervention effects, so the requirement to describe the mechanism of action of the intervention does not apply."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review is an integrative review of evaluation approaches rather than a primary study of complex interventions, and no logic model is presented in the rationale."
    }
  ],
  "confidence": 90
}

